def evidence(file,line=None,needle=None,kind='production-source',detail=None):
 file=Path(file)
 if line is None:
  lines=file.read_text().splitlines()
  hits=[i+1 for i,s in enumerate(lines)if needle in s]
  assert hits,(str(file),needle)
  line=hits[0]
 r={'file':str(file),'line':line,'kind':kind,'sha256':sha(file)}
 if detail:r['detail']=detail
 return r
def a(line):return evidence(MAIN,line)
def w(line):return evidence(WIDGET,line)
def s(rel,line=1):return evidence(T/rel,line,kind='recovered-source')
def d(rel,needle=None):return evidence(E/(rel.replace('/','-')+'.txt'),line=1 if needle is None else None,needle=needle,kind='original-disassembly')
def dev(rel,line=1):return evidence(P/'development'/rel,line,kind='existing-test-or-QA-evidence')
